/// One-time move of pre-rename data from the legacy `hchat` directories to
/// `fornax`, so anyone upgrading keeps their conversations, config, and tools.
/// Runs before any path is read; no-ops once the `fornax` dirs exist.
fn migrate_legacy_dirs() {
    use std::fs;
    // config + tools live under config_dir; the SQLite db under data_dir.
    // (these are the same directory on macOS, distinct on Linux.)
    for base in [dirs::config_dir(), dirs::data_dir()].into_iter().flatten() {
        let old = base.join("hchat");
        let new = base.join("fornax");
        if new.exists() || !old.exists() {
            continue;
        }
        if fs::rename(&old, &new).is_ok() {
            // Rename the db file (+ its WAL/SHM sidecars) to match the new name.
            for ext in ["", "-wal", "-shm"] {
                let from = new.join(format!("hchat.db{ext}"));
                if from.exists() {
                    let _ = fs::rename(&from, new.join(format!("fornax.db{ext}")));
                }
            }
        }
    }
}

#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    migrate_legacy_dirs();
    tauri::Builder::default()
        .manage(AppState::new())
        .setup(|app| {
            // Spawn the metrics poller + macmon thread; expose the active-target
            // handle so commands can retarget it.
            let target = metrics::start(app.handle().clone());
            app.manage(metrics::MetricsHandle(target));

            // Connect MCP servers in the background.
            let state = app.state::<AppState>();

            // Enforce the usage retention window once at startup.
            let retention = state.config.lock().unwrap().usage_retention_days;
            if retention > 0 {
                state.usage_storage.lock().unwrap().prune_usage(retention);
            }

            let mcp = state.mcp.clone();
            let servers = state.config.lock().unwrap().mcp_servers.clone();
            if !servers.is_empty() {
                tauri::async_runtime::spawn(async move {
                    mcp.connect_all(servers).await;
                });
            }
            Ok(())
        })
        .invoke_handler(tauri::generate_handler![
            // Config commands
            crate::commands::config_commands::get_config,
            crate::commands::config_commands::save_config,
            crate::commands::config_commands::fetch_models,

            // Chat commands
            crate::commands::chat_commands::list_conversations,
            crate::commands::chat_commands::load_conversation,
            crate::commands::chat_commands::delete_conversation,
            crate::commands::chat_commands::delete_all_conversations,
            crate::commands::chat_commands::rename_conversation,
            crate::commands::chat_commands::set_pinned,
            crate::commands::chat_commands::search_conversations,
            crate::commands::chat_commands::edit_message,
            crate::commands::chat_commands::message_siblings,
            crate::commands::chat_commands::walk_from,
            crate::commands::chat_commands::cancel_stream,
            crate::commands::chat_commands::resolve_tool,
            crate::commands::chat_commands::save_draft,

            // Project commands
            crate::commands::project_commands::list_projects,
            crate::commands::project_commands::create_project,
            crate::commands::project_commands::rename_project,
            crate::commands::project_commands::delete_project,
            crate::commands::project_commands::set_project_pinned,
            crate::commands::project_commands::set_conversation_project,

            // Usage commands
            crate::commands::usage_commands::usage_stats,
            crate::commands::usage_commands::clear_usage,
            crate::commands::usage_commands::run_benchmark,

            // MCP commands
            crate::commands::mcp_commands::list_mcp_servers,
            crate::commands::mcp_commands::reconnect_mcp,

            // System commands
            crate::commands::system_commands::export_conversation,
            crate::commands::system_commands::export_conversation_file,
            crate::commands::system_commands::list_agents,
            crate::commands::system_commands::list_presets,
