use rusqlite::{Connection, params};

pub struct AgentStorage {
    conn: Connection,
}

impl AgentStorage {
    pub fn new() -> Self {
        let conn = Connection::open(&Self::db_path()).expect("Failed to open database");
        conn.execute_batch("PRAGMA journal_mode=WAL; PRAGMA foreign_keys=ON;")
            .ok();
        let _ = conn.busy_timeout(std::time::Duration::from_secs(5));
        Self { conn }
    }

    fn db_path() -> std::path::PathBuf {
        dirs::data_dir()
            .unwrap_or_else(|| std::path::PathBuf::from("."))
            .join("fornax")
            .join("fornax.db")
    }

    /// Load agent configurations from the agents table
    pub fn load_agents(&self) -> Vec<serde_json::Value> {
        let mut stmt = match self.conn.prepare("SELECT config FROM agents") {
            Ok(s) => s,
            Err(_) => return Vec::new(),
        };
        match stmt.query_map([], |row| row.get::<_, String>(0)) {
            Ok(rows) => rows.filter_map(|result| {
                result.ok().and_then(|json_str| serde_json::from_str(&json_str).ok())
            }).collect(),
            Err(_) => Vec::new(),
        }
    }

    /// Save agent configuration
    pub fn save_agent(&self, agent_name: &str, config: &serde_json::Value) {
        let config_json = serde_json::to_string(config).unwrap_or_default();
        self.conn
            .execute(
                "INSERT OR REPLACE INTO agents (name, config, updated_at) VALUES (?1, ?2, datetime('now'))",
                params![agent_name, config_json],
            )
            .ok();
    }

    /// Delete agent configuration
    pub fn delete_agent(&self, agent_name: &str) {
        self.conn
            .execute("DELETE FROM agents WHERE name = ?1", params![agent_name])
            .ok();
    }
}

