/// All long-lived app state, managed by Tauri and shared across commands.
///
/// Each storage module wraps a rusqlite `Connection` (Send but not Sync), so they live
/// behind `Mutex`. Every command locks briefly for synchronous DB work and
/// drops the guard before any `.await` — never hold a lock across a suspend
/// point.
pub struct AppState {
    pub conversation_storage: Mutex<conversation_storage::ConversationStorage>,
    pub project_storage: Mutex<project_storage::ProjectStorage>,
    pub usage_storage: Mutex<usage_storage::UsageStorage>,
    pub preset_storage: Mutex<preset_storage::PresetStorage>,
    pub agent_storage: Mutex<agent_storage::AgentStorage>,
    pub config: Mutex<Config>,
    /// Cancellation tokens for in-flight chat streams, keyed by
    /// `conversation_id`. Each `run_turn` registers its token under its
    /// conversation; `cancel_stream(conversation_id)` fires (and removes) just
    /// that one, so streams in different chats run and cancel independently.
    pub cancel: Mutex<HashMap<i64, CancellationToken>>,
    /// Tool calls awaiting user approval, keyed by tool_call id. The streaming
    /// task parks a oneshot here and emits a `tool_approval` event; the
    /// `resolve_tool` command fulfills it with the user's decision.
    pub pending_approvals: Mutex<HashMap<String, PendingApproval>>,
    /// `(conversation_id, tool_name)` pairs the user chose to auto-approve for
    /// the rest of the session via "approve all in this conversation".
    pub auto_approved: Mutex<HashSet<(i64, String)>>,
    /// MCP client connections + discovered tools. Connected asynchronously after
    /// startup (see `lib.rs` setup).
    pub mcp: Arc<McpManager>,
}

impl AppState {
    pub fn new() -> Self {
        let config = Config::load();
        let conversation_storage = conversation_storage::ConversationStorage::new();
        let project_storage = project_storage::ProjectStorage::new();
        let usage_storage = usage_storage::UsageStorage::new();
        let preset_storage = preset_storage::PresetStorage::new();
        let agent_storage = agent_storage::AgentStorage::new();
        // Seed the default tools on first launch; tools are then (re)loaded from
        // disk on every turn, so edits take effect without a restart.
        tools::seed_defaults_if_empty(&tools::user_tools_dir());
        Self {
            conversation_storage: Mutex::new(conversation_storage),
            project_storage: Mutex::new(project_storage),
            usage_storage: Mutex::new(usage_storage),
            preset_storage: Mutex::new(preset_storage),
            agent_storage: Mutex::new(agent_storage),
            config: Mutex::new(config),
            cancel: Mutex::new(HashMap::new()),
            pending_approvals: Mutex::new(HashMap::new()),
            auto_approved: Mutex::new(HashSet::new()),
            mcp: McpManager::new(),
        }
    }

    /// Resolve the API key configured for `endpoint` (exact URL match against
    /// `saved_endpoints`). Returns `None` when the endpoint isn't saved or has
    /// no key — local servers (oMLX, llama.cpp) typically need none.
    pub fn api_key_for(&self, endpoint: &str) -> Option<String> {
        let cfg = self.config.lock().unwrap();
        cfg.saved_endpoints
            .iter()
            .find(|e| e.url == endpoint)
            .and_then(|e| e.api_key.clone())
    }
}

