                .unwrap_or(-1),
            None => self
                .conn
                .query_row(
                    "SELECT COALESCE(MAX(branch_index), -1) FROM messages
                     WHERE conversation_id = ?1 AND parent_id IS NULL",
                    params![conversation_id],
                    |row| row.get(0),
                )
                .unwrap_or(-1),
        };
