                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                model TEXT,
                system_prompt TEXT,
                temperature REAL,
                max_tokens INTEGER,
                use_max_tokens INTEGER NOT NULL DEFAULT 0,
